"""Produce comparison boards and offline delivery index from actual Blender renders."""
import pathlib,json,hashlib,zipfile,html
from PIL import Image,ImageDraw,ImageFont
R=pathlib.Path(__file__).resolve().parents[1];manifest=json.loads((R/'manifest.json').read_text());region=json.loads((R/'Validation/region_validation.json').read_text());scenes=json.loads((R/'Validation/scene_integrity.json').read_text());rows=[]
font='/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc';title=ImageFont.truetype(font,38);label=ImageFont.truetype(font,25);small=ImageFont.truetype(font,21)
def board(name,pairs,heading,subheading,footer):
 w=1920;im=Image.new('RGB',(w,990),'#e5ebec');d=ImageDraw.Draw(im);d.text((30,18),heading,font=title,fill='#20343e');d.text((30,76),subheading,font=label,fill='#48636b')
 for i,(file,top,caption) in enumerate(pairs):
  x=30+i*960;d.text((x,135),top,font=label,fill='#20343e');src=Image.open(R/'Previews'/file).convert('RGB');src.thumbnail((900,680),Image.Resampling.LANCZOS);im.paste(src,(x,185+(680-src.height)//2));d.text((x,875),caption,font=small,fill='#20343e')
 d.text((30,942),footer,font=small,fill='#48636b');im.save(R/'Previews'/name)
board('hall_scale_comparison.png', [('hall_before_eye_1p65m.png','调整前 / 未交付的紧凑草稿','32×20 m 建筑 / 8 m 高 / 内部柱网 / 8 m 夹层'),('hall_after_eye_1p65m.png','调整后 / 大跨度主厅','连续净跨度 27.44×19.20 m / 最低屋架 9.495 m')], '主厅空间尺度修正 / 实际 Blender 渲染','同机位 · 24 mm · 眼高 1.65 m · 人物 1.8 m · 同灯光与采样','4 m 基础模块不变；通过移除内柱、收窄夹层、加高屋顶形成大空间。基础 PBR，非最终美术。')
board('pump_annex_scale_comparison.png',[('pump_annex_before_eye.png','原第三批泵房附楼','整体室内 7.7×23.2 m / 层间净高 3.75 m'),('pump_annex_after_eye.png','可选通高版本','主要通高段 7.7×19.5 m / 最低梁下 7.495 m')],'泵房附楼 / 可选空间修正','同机位 · 24 mm · 眼高 1.65 m · 人物 1.8 m · 同灯光与采样','保留东北角 4×4 m 上层入口平台；并非全长均通高。该版本单独保存，不替换主双区场景。')
for e in manifest['assets']:
 p=R/e['path'];sp=json.loads((p/'spec.json').read_text());v=json.loads((p/'validation.json').read_text());ex=json.loads((p/'export_validation.json').read_text());im=json.loads((p/'image_validation.json').read_text());inter=json.loads((p/'interface_validation.json').read_text());rows.append({'asset_id':e['asset_id'],'path':e['path'],'dimensions_m':sp['dimensions'],'triangles':v['geometry']['triangles'],'collision_hulls':v['collision_hulls'],'pixels_per_meter':v['orthographic_validation']['pixels_per_meter'],'status':'PASS' if all(q['status']=='PASS' for q in [v,ex,im,inter]) else 'FAIL','max_export_bounds_error_m':max(q['max_bounds_error_m'] for q in ex['exports'].values()),'max_silhouette_error_px':max(q['maximum_error_px'] for q in im['views'].values())})
freeze=[]
for batch,zpath in [(1,R.parent.parent/'NuclearPlant_Batch01.zip'),(2,R.parent.parent/'NuclearPlant_Batch02_Delivery/NuclearPlant_Batch02_Full.zip'),(3,R.parent.parent/'NuclearPlant_Batch03_Delivery/NuclearPlant_Batch03_Full.zip')]:
 with zipfile.ZipFile(zpath) as z:
  for name in z.namelist():
   if name.endswith('/'):continue
   actual=R.parent.parent/name;expected=hashlib.sha256(z.read(name)).hexdigest();got=hashlib.sha256(actual.read_bytes()).hexdigest();freeze.append({'batch':batch,'path':name,'sha256':got,'matches_original_delivery':got==expected})
(R/'Validation/prior_batches_freeze_after.json').write_text(json.dumps({'status':'PASS' if all(e['matches_original_delivery'] for e in freeze) else 'FAIL','file_count':len(freeze),'files':freeze},indent=2))
libs=json.loads((R/'Validation/packaged_scene_libraries.json').read_text());pump=json.loads((R/'Validation/pump_annex_option.json').read_text())
summary={'project':manifest['project'],'batch':4,'revision':'LargeSpace','scope':manifest['scope'],'overall_status':'PASS' if all(e['status']=='PASS' for e in rows) and region['status']=='PASS' and all(z['status']=='PASS' for z in scenes+libs) and pump['status']=='PASS' and all(e['matches_original_delivery'] for e in freeze) else 'FAIL','built_with':'Blender 4.3.2','assets':rows,'new_asset_count':3,'new_asset_triangles':sum(e['triangles'] for e in rows),'orthographic_images':9,'reference_images':3,'module_instances_in_connected_scene':region['module_instance_count'],'reused_asset_types':19,'region_checks':len(region['checks']),'scene_check_counts':[len(s['checks']) for s in scenes],'large_hall_clear_span_m':[27.4375,19.2],'minimum_main_hall_overhead_m':9.495,'main_aisle_width_m':6,'minimum_road_bridge_clearance_m':7.23,'pump_option_main_clear_m':[7.7,19.5,7.495],'max_export_bounds_error_m':max(e['max_export_bounds_error_m'] for e in rows),'max_orthographic_silhouette_error_px':max(e['max_silhouette_error_px'] for e in rows),'frozen_prior_files_verified':len(freeze),'realized_zones':['04_PUMP','07_SERVICE'],'remaining_graybox_zones':6,'relocation_test':json.loads((R/'Validation/relocation_open_test.json').read_text())['status'],'ue_editor_test':'NOT_RUN','visual_review':'Validation/visual_review.md','comparison_renders':'Same camera, light setup, sampling, with 1.8 m geometry and 1.65 m camera eye height. Not AI images.','pending':['Six original graybox zones','Actual UE import, collision setup, capsule traversal, vehicle and runtime performance tests','Final realistic textures, wear, decals and lighting','LOD and lightmap production packing']}
(R/'Validation/final_summary.json').write_text(json.dumps(summary,indent=2))
body=''
for r in rows:
 p=r['path'];body+=f'<article><h2>{html.escape(r["asset_id"])}</h2><p>{r["dimensions_m"]} m · {r["triangles"]:,} triangles · {r["status"]}</p><img loading="lazy" src="{p}/orthographic_sheet.png"><p><a href="{p}/model.blend">Blender</a> · <a href="{p}/export.fbx">FBX</a> · <a href="{p}/export.glb">GLB</a> · <a href="{p}/spec.json">Spec</a> · <a href="{p}/reference_sheet.png">AI 外观参考</a></p></article>'
head='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>NPP / 大空间修订</title><style>body{margin:0;background:#e5ebec;color:#20343e;font:16px system-ui;line-height:1.7}main{max-width:1280px;margin:auto;padding:40px 24px}h1{font-size:42px}article{background:white;padding:24px;margin:28px 0;border-radius:16px}img{width:100%;height:auto}a{color:#126a78}</style><main><small>NPP / SECTOR K-17 / BATCH 04 LARGE SPACE</small><h1>大跨度主厅与真实双区动线</h1><p>主厅连续净跨度约 27.44×19.20 m，最低屋架净高 9.495 m，中央主通道宽 6 m。泵区与物流区由地面和跨路高架连接。4 m 模块保持原尺寸；其他 6 个功能区仍为灰盒。基础 PBR，非最终 AAA 场景。</p><p><a href="README_zh.md">使用说明</a> · <a href="Region/pump_service_connected.blend">双区场景</a> · <a href="Region/site_with_pump_service.blend">全站上下文</a> · <a href="Region/pump_annex_double_height_option.blend">可选通高泵房</a> · <a href="Validation/final_summary.json">验收摘要</a></p>'''
for file,caption in [('hall_scale_comparison.png','同机位室内尺度对比'),('hall_after_eye_across_span.png','大跨度横向视角 / 24 mm，眼高 1.65 m'),('service_cutaway.png','去顶剖视：夹层和主通道'),('pump_service_connected.png','双区与高架连接'),('connected_top.png','实际组合俯视'),('pump_annex_scale_comparison.png','可选泵房通高对比'),('site_with_pump_service.png','全局上下文：两个区域已替换')]:head+=f'<h2>{caption}</h2><img loading="lazy" src="Previews/{file}">'
(R/'index.html').write_text(head+body+'</main></html>');print(json.dumps(summary,indent=2))
